const PACKS={essential:'consultation',premium:'consultation',vip:'chronic',coaching:'chronic'};
const PACK_SPEECH={fr:{essential:'Pour commencer, le pack Essentiel est à vingt-cinq mille francs C F A. Il comprend une consultation médicale à domicile, les constantes de base, une prescription si elle est indiquée et des conseils de santé.',premium:'Le pack Premium est à cinquante mille francs C F A. Il reprend le pack Essentiel et ajoute la livraison des médicaments prescrits, un suivi téléphonique pendant sept jours et une priorité de rappel.',vip:'Le pack V I P est à cent mille francs C F A par mois. Il comprend quatre consultations mensuelles, une ligne prioritaire, le suivi des maladies chroniques et un médecin référent.',coaching:'Enfin, le Coaching Santé Premium peut aller jusqu à deux cent mille francs C F A par mois. Il est destiné aux personnes qui souhaitent un accompagnement plus complet en nutrition, activité physique, tension, glycémie, prévention et orientation spécialisée.'},en:{essential:'The Essential plan costs twenty-five thousand C F A francs. It includes a home medical consultation, basic vital measurements, a prescription when indicated, and health advice.',premium:'The Premium plan costs fifty thousand C F A francs. It includes the Essential plan plus delivery of prescribed medication, seven days of phone follow-up, and priority call back.',vip:'The V I P plan costs one hundred thousand C F A francs per month. It includes four monthly consultations, a priority phone line, chronic disease follow-up, and a reference physician.',coaching:'Finally, Premium Health Coaching can cost up to two hundred thousand C F A francs per month. It is designed for people who want more complete support with nutrition, physical activity, blood pressure, glucose monitoring, prevention and specialist referral.'}};
let lang=localStorage.getItem('ps_lang')||'fr';let selectedService='';let step=1;let voiceOn=false;
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
function tr(k){return I18N[lang][k]||k}
function applyLang(){document.documentElement.lang=lang;localStorage.setItem('ps_lang',lang);qa('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(I18N[lang][k]) el.textContent=I18N[lang][k]});qa('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));qa('[data-ph-fr]').forEach(el=>el.placeholder=el.dataset['ph'+(lang==='fr'?'Fr':'En')]);document.title=lang==='fr'?'PrévenSanté CI | Soins médicaux à domicile à San Pedro':'PrévenSanté CI | Home medical care in San Pedro';q('#metaDescription').content=lang==='fr'?"PrévenSanté CI, clinique mobile à domicile à San Pedro : consultation, soins infirmiers, prélèvements, médicaments sur ordonnance, coordination d'examens et rendez-vous spécialisés.":'PrévenSanté CI, mobile home-care clinic in San Pedro: consultations, nursing care, lab sampling, prescription medication delivery, test coordination and specialist appointments.';renderChoices();if(selectedService)renderService();if(q('#preventcauseriePanel').classList.contains('open'))resetPreventcauserie();if(q('#modal').classList.contains('open')){showStep();renderService();localizeFormExtras()}}
qa('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;applyLang()});
function iconText(name){const icons={consultation:'🩺',nursing:'💉',lab:'🧪',meds:'💊',imaging:'🩻',specialist:'🏥',chronic:'❤️',tele:'📱',callback:'☎️'};return icons[name]||'•'}
function renderChoices(){const keys=['consultation','nursing','lab','meds','imaging','specialist','chronic','tele','callback'];q('#serviceChoices').innerHTML=keys.map(k=>`<button type="button" class="choice ${selectedService===k?'selected':''}" data-choice="${k}"><span style="font-size:1.35rem">${iconText(k)}</span><br>${SERVICES[k][lang].name}</button>`).join('');qa('[data-choice]').forEach(b=>b.onclick=()=>{selectedService=b.dataset.choice;q('#serviceField').value=SERVICES[selectedService][lang].name;renderChoices();renderService();if(innerWidth<681){step=2;showStep()}})}

function localizeFormExtras(){
  const fr=lang==='fr';
  q('#consentText').textContent=fr?"J’accepte que PrévenSanté CI traite les informations et, si j’en joins, les documents nécessaires à cette demande afin de me recontacter et organiser la prise en charge.":"I agree that PrévenSanté CI may process the information and any document I attach as needed to contact me and organise the requested service.";
  q('#formPrivacyText').textContent=fr?"Décrivez uniquement les éléments utiles à l’organisation de la prise en charge. Ce formulaire ne constitue pas le dossier médical du patient ; le dossier clinique est tenu séparément par PrévenSanté CI.":"Provide only the information needed to organise care. This form is not the patient medical record; the clinical record is maintained separately by PrévenSanté CI.";
  q('#documentStatusBox label').textContent=fr?"Avez-vous une ordonnance, un bulletin ou une demande d’examen ?":"Do you have a prescription, medical order or test request?";
  const opts=q('#documentStatus').options; if(opts.length>1){opts[0].textContent=fr?'Non':'No';opts[1].textContent=fr?'Oui, document disponible':'Yes, document available'}
  const photo=q('label[for=photoInput]'),file=q('label[for=fileInput]');if(photo){photo.querySelector('b').textContent=fr?'Prendre une photo':'Take a photo';photo.querySelector('small').textContent=fr?'Ordonnance, bulletin, demande d’examen…':'Prescription, medical order, test request…'}if(file){file.querySelector('b').textContent=fr?'Choisir un fichier':'Choose a file';file.querySelector('small').textContent=fr?'Image ou PDF':'Image or PDF'}
  updateFileStatus();
}
function renderService(){
  if(!selectedService)return;
  const s=SERVICES[selectedService],c=s[lang];
  q('#modalTitle').textContent=c.title;
  q('#serviceBrief').innerHTML=`<b>${c.title}</b><br>${c.brief}`;
  q('#detailLabel').textContent=c.detail || (lang==='fr'?'Décrivez brièvement votre besoin':'Briefly describe your need');
  q('#detailText').placeholder=c.ph || '';
  q('#optionLabel').textContent=c.option || (lang==='fr'?'Option utile':'Useful option');
  q('#optionSelect').innerHTML=(c.opts||[]).map(x=>`<option>${x}</option>`).join('');
  q('#companyFields').style.display=s.enterprise?'grid':'none';
  q('#companyName').required=!!s.enterprise;
  const needsDoc=['meds','imaging','lab','nursing','specialist'].includes(selectedService);
  q('#documentStatusBox').hidden=!needsDoc;
  const upload=q('#uploadBox');
  upload.hidden=!c.upload;
  if(c.upload){q('#uploadTitle').textContent=c.upload;q('#uploadHelp').textContent=c.help||''}
  q('#submit').textContent=c.submit || (lang==='fr'?'Envoyer ma demande':'Send my request');
  q('#serviceField').value=c.name;
}
function openModal(service){
  q('#easyOverlay').classList.remove('open');q('#drawer').classList.remove('open');selectedService=service||'';step=selectedService?2:1;requestRef='';
  q('#rdvForm').reset();q('#detailCount').textContent='0';q('#fileStatus').textContent=lang==='fr'?'Aucun document sélectionné.':'No document selected.';
  q('#success').style.display='none';q('#steps').style.display='block';q('#formActions').style.display='flex';q('#modal').classList.add('open');q('#modal').setAttribute('aria-hidden','false');document.body.classList.add('lock');renderChoices();if(selectedService)renderService();showStep();localizeFormExtras();setTimeout(()=>q('.step.active')?.querySelector('button,input,select,textarea')?.focus(),40)
}
function closeModal(){q('#modal').classList.remove('open');q('#modal').setAttribute('aria-hidden','true');document.body.classList.remove('lock')}
qa('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));qa('[data-callback]').forEach(b=>b.onclick=()=>openModal('callback'));qa('[data-pack]').forEach(b=>b.onclick=()=>openModal(PACKS[b.dataset.pack]));q('#modalClose').onclick=closeModal;q('#successClose').onclick=closeModal;q('#modal').onclick=e=>{if(e.target===q('#modal'))closeModal()};
function validateStep(){
  if(step===1&&!selectedService){alert(lang==='fr'?'Choisissez un service.':'Please choose a service.');return false}
  if(step===2&&selectedService!=='callback'&&!q('#detailText').value.trim()){alert(lang==='fr'?'Décrivez brièvement vos symptômes ou votre besoin.':'Briefly describe your symptoms or need.');q('#detailText').focus();return false}
  if(step===3&&!q('#zoneField').value.trim()){q('#zoneField').focus();return false}
  if(step===4){if(SERVICES[selectedService]?.enterprise&&!q('#companyName').value.trim()){alert(lang==='fr'?"Indiquez le nom de l’entreprise.":'Enter the company name.');q('#companyName').focus();return false}if(!q('#nameField').value.trim()){q('#nameField').focus();return false}if(!q('#phoneField').value.trim()){q('#phoneField').focus();return false}if(!q('#consentContact').checked){alert(lang==='fr'?'Veuillez accepter la politique de confidentialité pour continuer.':'Please accept the privacy policy to continue.');q('#consentContact').focus();return false}}
  return true
}
function showStep(){
  qa('.step').forEach(s=>s.classList.toggle('active',Number(s.dataset.step)===step));q('#progress').style.width=(step*20)+'%';q('#prev').style.visibility=step===1?'hidden':'visible';q('#next').style.display=step===5?'none':'inline-flex';q('#sendWhatsApp').style.display=step===5?'inline-flex':'none';q('#submit').style.display=step===5?'inline-flex':'none';if(step===2)renderService();if(step===5)renderSummary();
  const fr={1:['Quel service souhaitez-vous ?','Choisissez simplement votre besoin.'],2:['Décrivez brièvement votre besoin','Le formulaire s’adapte au service choisi. Indiquez seulement les éléments utiles.'],3:['Où et quand souhaitez-vous être pris en charge ?','Indiquez la zone et le créneau souhaité.'],4:['Comment pouvons-nous vous joindre ?','L’équipe vous rappellera pour confirmer le besoin, la disponibilité et le tarif.'],5:['Vérifiez votre demande','Relisez les informations ci-dessous avant l’envoi.']};
  const en={1:['Which service do you need?','Simply choose what you need.'],2:['Briefly describe your need','The form adapts to the selected service. Provide only useful information.'],3:['Where and when would you like the service?','Enter the area and preferred time.'],4:['How can we reach you?','The team will call you back to confirm the need, availability and price.'],5:['Review your request','Check the information below before sending.']};
  const a=(lang==='fr'?fr:en)[step];q('#step'+step+'Heading').textContent=a[0];q('#step'+step+'Help').textContent=a[1];
  q('#sendWhatsApp').textContent=lang==='fr'?'Envoyer par WhatsApp':'Send by WhatsApp';q('#submit').textContent=lang==='fr'?'Envoyer par e-mail':'Send by email';const ch=q('#channelHelp');if(ch)ch.textContent=lang==='fr'?'WhatsApp ouvre un message déjà structuré à vérifier puis envoyer. L’e-mail transmet directement le formulaire à PrévenSanté CI.':'WhatsApp opens a structured message for you to review and send. Email sends the form directly to PrévenSanté CI.';
  if(voiceOn)speak(a[0]+'. '+a[1])
}
q('#prev').onclick=()=>{if(step>1){step--;showStep()}};q('#next').onclick=()=>{if(!validateStep())return;step++;showStep()};
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
let requestRef='';
function makeRequestRef(){if(requestRef)return requestRef;const d=new Date(),pad=n=>String(n).padStart(2,'0'),stamp=`${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`,rnd=Math.random().toString(36).slice(2,6).toUpperCase();requestRef=`PSCI-${stamp}-${rnd}`;return requestRef}
function requestData(){const f=new FormData(q('#rdvForm'));return {ref:makeRequestRef(),service:SERVICES[selectedService]?.[lang]?.name||selectedService||'-',detail:f.get('Description breve')||'-',option:f.get('Option service')||'-',zone:f.get('Quartier / zone')||'-',date:f.get('Date souhaitee')||'-',slot:f.get('Creneau')||'-',name:f.get('Nom et prenoms')||'-',phone:f.get('Telephone')||'-',email:f.get('email')||'-',contact:f.get('Contact prefere')||'-',doc:f.get('Document disponible')||'Non'}}
function prepareTransmission(channel){const d=requestData(),now=new Date().toISOString();q('#referenceField').value=d.ref;q('#channelField').value=channel;q('#requestTimestamp').value=now;q('#replyToField').value=d.email==='-'?'':d.email;q('#subjectField').value=`PrévenSanté CI | ${d.ref} | ${d.service} | ${d.name}`;q('#nextField').value=`https://prevensanteci.github.io/?sent=1&ref=${encodeURIComponent(d.ref)}`;return d}
function whatsappMessage(d){const files=[q('#photoInput').files[0],q('#fileInput').files[0]].filter(Boolean);const lines=lang==='fr'?[`*PRÉVENSANTÉ CI — DEMANDE DE PRISE EN CHARGE*`,`Référence : *${d.ref}*`,``,`*Patient*`,`Nom : ${d.name}`,`Téléphone : ${d.phone}`,`Quartier / zone : ${d.zone}`,``,`*Demande*`,`Service : ${d.service}`,`Besoin : ${d.detail}`,`Option : ${d.option}`,`Date souhaitée : ${d.date}`,`Créneau : ${d.slot}`,`Document disponible : ${d.doc}`,files.length?`Pièce jointe : à joindre manuellement dans cette conversation (${files.map(f=>f.name).join(', ')})`:null,``,`Contact préféré : ${d.contact}`,``,`Merci de confirmer la disponibilité, le tarif et l’organisation de la prise en charge.`,``,`En cas d’urgence vitale : hôpital le plus proche — SAMU 185 / Pompiers 180.`]:[`*PRÉVENSANTÉ CI — CARE REQUEST*`,`Reference: *${d.ref}*`,``,`*Patient*`,`Name: ${d.name}`,`Phone: ${d.phone}`,`Area: ${d.zone}`,``,`*Request*`,`Service: ${d.service}`,`Need: ${d.detail}`,`Option: ${d.option}`,`Preferred date: ${d.date}`,`Time slot: ${d.slot}`,`Document available: ${d.doc}`,files.length?`Attachment: please attach manually in this WhatsApp chat (${files.map(f=>f.name).join(', ')})`:null,``,`Preferred contact: ${d.contact}`,``,`Please confirm availability, price and practical arrangements.`,``,`Life-threatening emergency: nearest hospital — SAMU 185 / Firefighters 180.`];return lines.filter(Boolean).join('\n')}
function renderSummary(){
  const d=requestData(),files=[q('#photoInput').files[0],q('#fileInput').files[0]].filter(Boolean);const lines=[`<b>${lang==='fr'?'Référence':'Reference'}:</b> ${esc(d.ref)}`,`<b>Service:</b> ${esc(d.service)}`,`<b>${lang==='fr'?'Description':'Description'}:</b> ${esc(d.detail)}`,`<b>${lang==='fr'?'Option':'Option'}:</b> ${esc(d.option)}`,`<b>${lang==='fr'?'Zone':'Area'}:</b> ${esc(d.zone)}`,`<b>${lang==='fr'?'Date':'Date'}:</b> ${esc(d.date)}`,`<b>${lang==='fr'?'Créneau':'Time slot'}:</b> ${esc(d.slot)}`,`<b>${lang==='fr'?'Nom':'Name'}:</b> ${esc(d.name)}`,`<b>${lang==='fr'?'Téléphone':'Phone'}:</b> ${esc(d.phone)}`,`<b>${lang==='fr'?'Contact préféré':'Preferred contact'}:</b> ${esc(d.contact)}`];if(d.doc)lines.push(`<b>${lang==='fr'?'Document disponible':'Document available'}:</b> ${esc(d.doc)}`);if(files.length)lines.push(`<b>${lang==='fr'?'Pièce jointe':'Attachment'}:</b> ${files.map(x=>esc(x.name)).join(', ')}`);q('#summary').innerHTML=lines.join('<br>')
}
function updateFileStatus(){const files=[q('#photoInput').files[0],q('#fileInput').files[0]].filter(Boolean);q('#fileStatus').textContent=files.length?(lang==='fr'?'Sélection : ':'Selected: ')+files.map(f=>f.name).join(' · '):(lang==='fr'?'Aucun document sélectionné.':'No document selected.')}
q('#photoInput').addEventListener('change',updateFileStatus);q('#fileInput').addEventListener('change',updateFileStatus);q('#detailText').addEventListener('input',()=>q('#detailCount').textContent=q('#detailText').value.length);
q('#sendWhatsApp').addEventListener('click',()=>{
  if(step!==5||!validateStep())return;const d=prepareTransmission('WhatsApp'),url='https://wa.me/2250712619655?text='+encodeURIComponent(whatsappMessage(d));try{localStorage.setItem('prevensante_last_request',JSON.stringify({reference:d.ref,channel:'WhatsApp',timestamp:new Date().toISOString()}))}catch(_){}window.location.href=url
});
q('#rdvForm').addEventListener('submit',e=>{
  if(step!==5||!validateStep()){e.preventDefault();return}
  const files=[q('#photoInput').files[0],q('#fileInput').files[0]].filter(Boolean);const total=files.reduce((n,f)=>n+f.size,0);if(total>10*1024*1024){e.preventDefault();alert(lang==='fr'?'Les pièces jointes dépassent 10 Mo au total. Réduisez leur taille ou joignez un seul document.':'Attachments exceed 10 MB in total. Reduce their size or attach only one file.');return}
  const d=prepareTransmission('E-mail');const consentId=(crypto.randomUUID?crypto.randomUUID():('consent-'+Date.now()+'-'+Math.random().toString(16).slice(2))),consentTime=new Date().toISOString();q('#consentId').value=consentId;q('#consentTimestamp').value=consentTime;try{localStorage.setItem('prevensante_consent_receipt',JSON.stringify({id:consentId,timestamp:consentTime,version:'2026-08-08-v2',language:lang}))}catch(_){}
  q('#submit').disabled=true;q('#submit').textContent=lang==='fr'?'Envoi e-mail...':'Sending email...';
});
function showSentSuccess(){const u=new URL(location.href);if(u.searchParams.get('sent')!=='1')return;const ref=u.searchParams.get('ref')||'';q('#modal').classList.add('open');q('#modal').setAttribute('aria-hidden','false');document.body.classList.add('lock');q('#steps').style.display='none';q('#formActions').style.display='none';q('#success').style.display='block';q('#successTitle').textContent=lang==='fr'?'Demande transmise par e-mail.':'Request sent by email.';q('#successText').textContent=lang==='fr'?"Votre demande a été transmise au service de messagerie de PrévenSanté CI. L’équipe vous recontactera pour confirmer la prise en charge.":'Your request was sent to the PrévenSanté CI messaging service. The team will contact you to confirm the service.';q('#successRef').textContent=ref?(lang==='fr'?'Référence : ':'Reference: ')+ref:'';u.searchParams.delete('sent');u.searchParams.delete('ref');history.replaceState({},'',u.pathname+(u.search||'')+u.hash)}
setTimeout(showSentSuccess,80);
function openEasy(){q('#drawer').classList.remove('open');q('#easyOverlay').classList.add('open');document.body.classList.add('lock')}function closeEasy(){q('#easyOverlay').classList.remove('open');document.body.classList.remove('lock');q('#heroEasy')?.focus()}q('#easyModeBtn')?.addEventListener('click',openEasy);q('#easyMobile').onclick=openEasy;q('#drawerEasy').onclick=openEasy;q('#easyClose').onclick=closeEasy;q('#heroEasy').onclick=openEasy;
function openDrawer(){q('#drawer').classList.add('open');q('#drawer').setAttribute('aria-hidden','false');q('#menuBtn').setAttribute('aria-expanded','true');document.body.classList.add('lock');setTimeout(()=>q('#drawerClose')?.focus(),30)}
function closeDrawer(){q('#drawer').classList.remove('open');q('#drawer').setAttribute('aria-hidden','true');q('#menuBtn').setAttribute('aria-expanded','false');document.body.classList.remove('lock');q('#menuBtn')?.focus()}
q('#menuBtn').onclick=openDrawer;q('#drawerClose').onclick=closeDrawer;q('#drawerBg').onclick=closeDrawer;qa('[data-close-drawer]').forEach(a=>a.onclick=closeDrawer);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(q('#modal').classList.contains('open'))closeModal();else if(q('#easyOverlay').classList.contains('open'))closeEasy();else if(q('#drawer').classList.contains('open'))closeDrawer();else if(q('#preventcauseriePanel')?.classList.contains('open'))q('#preventcauseriePanel').classList.remove('open')}});
const VOICE_GUIDE={
fr:`Bonjour, et bienvenue chez Préven Santé Côte d’Ivoire.

Si vous êtes ici, c’est sans doute parce que vous cherchez une solution simple pour vous-même, un parent ou un proche. À San Pedro, notre rôle est de rapprocher les soins du patient, surtout quand se déplacer devient difficile.

Concrètement, nous pouvons organiser une consultation médicale à domicile, des soins infirmiers, un prélèvement biologique, la livraison de médicaments sur ordonnance, le suivi d’une maladie chronique, ou encore vous aider à organiser une imagerie, un rendez-vous chez un spécialiste, en clinique ou à l’hôpital.

Voici comment en bénéficier. Choisissez simplement le service qui correspond à votre besoin. Répondez à quelques questions courtes, puis laissez votre numéro de téléphone. L’équipe Préven Santé vous rappelle ensuite pour confirmer la disponibilité, le coût et l’organisation pratique.

Si vous préférez parler plutôt qu’écrire, utilisez le mode Très facile, appelez-nous directement, ou envoyez un message vocal sur WhatsApp.

Et surtout, si la situation est grave ou vitale, n’attendez pas une réponse du site. Allez immédiatement à l’hôpital le plus proche.`,
en:`Hello, and welcome to PrévenSanté Côte d’Ivoire.

If you are here, you may be looking for a simple solution for yourself, a parent or someone close to you. In San Pedro, our role is to bring care closer to the patient, especially when travelling becomes difficult.

We can arrange a medical home visit, nursing care, laboratory sampling, prescription medication delivery, chronic care follow-up, or help organise imaging, a specialist appointment, a clinic visit or a hospital appointment.

Here is how it works. Choose the service that matches your need, answer a few short questions, then leave your phone number. The PrévenSanté team will call you back to confirm availability, cost and practical arrangements.

If you would rather speak than type, use Very Easy mode, call us directly, or send a WhatsApp voice note.

And if the situation is serious or life-threatening, do not wait for a reply from the website. Go immediately to the nearest hospital.`};
function voiceScore(v){const n=(v.name+' '+(v.lang||'')).toLowerCase();let s=0;const target=lang==='fr'?'fr':'en';if((v.lang||'').toLowerCase().startsWith(target))s+=140;if(/natural|premium|enhanced|online/.test(n))s+=120;if(/google/.test(n))s+=90;if(/microsoft/.test(n))s+=82;if(/apple|siri/.test(n))s+=75;if(/samsung/.test(n))s+=55;if(lang==='fr'&&/fr-fr|français|french|denise|henri|hortense|audrey|thomas|amelie|amélie|remy|rémy|eloise|éloise/.test(n))s+=55;if(lang==='en'&&/en-us|en-gb|english/.test(n))s+=45;if(/espeak|compact|festival|pico/.test(n))s-=260;return s}
function bestVoice(){const vs=speechSynthesis.getVoices();return [...vs].sort((a,b)=>voiceScore(b)-voiceScore(a))[0]||vs[0]}
let speechRun=0;
function spokenText(t){return String(t||'').replace(/PrévenSanté CI/g,lang==='fr'?'Préven Santé Côte d’Ivoire':'PrévenSanté Côte d’Ivoire').replace(/FCFA/g,lang==='fr'?'francs C F A':'C F A francs').replace(/\bVIP\b/g,'V I P').replace(/\bHTA\b/g,'H T A').trim()}
function speak(text){if(!('speechSynthesis'in window))return;speechSynthesis.cancel();speechRun++;const run=speechRun;const voice=bestVoice();const raw=spokenText(text);const parts=raw.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);let i=0;const next=()=>{if(run!==speechRun||i>=parts.length)return;const u=new SpeechSynthesisUtterance(parts[i++]);if(voice)u.voice=voice;u.lang=lang==='fr'?'fr-FR':'en-US';u.rate=lang==='fr'?.94:.95;u.pitch=1.01;u.volume=1;u.onend=()=>setTimeout(next,i===1?360:300);u.onerror=()=>setTimeout(next,280);speechSynthesis.speak(u)};next()}
function startVoice(){voiceOn=true;speak(VOICE_GUIDE[lang])}
q('#voiceGuideBtn2')?.addEventListener('click',startVoice);q('#drawerVoice').onclick=startVoice;q('#easyVoice').onclick=startVoice;q('#heroVoice').onclick=startVoice;
q('#listenAllPacks')?.addEventListener('click',()=>speak(Object.values(PACK_SPEECH[lang]).join('\n\n')));
q('#listenAllPacksTop')?.addEventListener('click',()=>speak(Object.values(PACK_SPEECH[lang]).join('\n\n')));
function resetPreventcauserie(){q('#preventcauserieMsgs').innerHTML='';assistantMessage(lang==='fr'?"Bonjour, je suis l’Assistant Preventcauserie. Dites-moi simplement ce que vous souhaitez organiser : une consultation, un prélèvement, des médicaments, un examen, un spécialiste ou une demande entreprise.":"Hello, I’m the Preventcauserie Assistant. Tell me what you would like to arrange: a consultation, a lab sample, medication delivery, a test, a specialist appointment or a company service.")}function assistantMessage(t){const d=document.createElement('div');d.className='msg assistant';d.textContent=t;q('#preventcauserieMsgs').appendChild(d);q('#preventcauserieMsgs').scrollTop=q('#preventcauserieMsgs').scrollHeight}function visitorMessage(t){const d=document.createElement('div');d.className='msg user';d.textContent=t;q('#preventcauserieMsgs').appendChild(d);q('#preventcauserieMsgs').scrollTop=q('#preventcauserieMsgs').scrollHeight}function preventcauserieReply(raw){const t=raw.toLowerCase();if(/urgent|urgence|respir|inconscient|convuls|saign|bleed|chest pain|thorac/.test(t))return lang==='fr'?"Si la situation est grave ou vitale, allez directement à l'hôpital. N'attendez pas une réponse du site.":'If the situation is serious or life-threatening, go directly to the hospital. Do not wait for a response from the website.';if(/entreprise|company|employee|salari|hse|workplace/.test(t))return lang==='fr'?"Pour une entreprise, choisissez dépistage, sensibilisation, journée santé, programme santé, orientation ou offre sur mesure dans la section Entreprises.":'For a company, choose screening, awareness, a health day, an employee health programme, referral or a custom proposal in the Companies section.';if(/medic|ordonnance|pharmacy|pharmacie/.test(t))return lang==='fr'?"La livraison concerne les médicaments prescrits. Une ordonnance valide est nécessaire et le coût est confirmé avant l'achat.":'Medication delivery is for prescribed medicines. A valid prescription is required and the cost is confirmed before purchase.';if(/blood|prise de sang|lab|pr[eé]l[eè]vement/.test(t))return lang==='fr'?"Nous pouvons organiser un prélèvement à domicile puis la coordination avec le laboratoire.":'We can arrange home sample collection and coordinate with the laboratory.';return lang==='fr'?"Je peux vous orienter vers une consultation, un prélèvement, une livraison de médicaments, une imagerie, un spécialiste ou une offre entreprise.":'I can guide you to a medical consultation, lab sampling, medication delivery, imaging, a specialist or a corporate service.'}
q('#preventcauserieLaunch').onclick=()=>{q('#preventcauseriePanel').classList.toggle('open');if(q('#preventcauseriePanel').classList.contains('open')&&!q('#preventcauserieMsgs').children.length)resetPreventcauserie()};q('#preventcauserieClose').onclick=()=>q('#preventcauseriePanel').classList.remove('open');q('#preventcauserieForm').onsubmit=e=>{e.preventDefault();const inp=q('#preventcauserieInput'),txt=inp.value.trim();if(!txt)return;visitorMessage(txt);inp.value='';setTimeout(()=>assistantMessage(preventcauserieReply(txt)),250)};qa('[data-preventcauserie]').forEach(b=>b.onclick=()=>{const k=b.dataset.preventcauserie;if(k==='consultation')openModal('consultation');else if(k==='lab')openModal('lab');else if(k==='meds')openModal('meds');else if(k==='business')location.hash='business';else assistantMessage(preventcauserieReply('urgence'))});
const today=new Date().toISOString().split('T')[0];const dateInput=q('input[type=date]');if(dateInput)dateInput.min=today;applyLang();renderChoices();
